n=17;k=8;g=[]
for r in range(n):
 row=[0]*n
 if r<=k:
  row[k-r]=2; row[k+r]=2
 else:
  for c in range(n):
   if (c-(r-k+1))%4==0: row[c]=1
 g.append(row)
print(json.dumps(g,separators=(',',':')))

